function extractList(response, keys) {
  let value = response?.data ?? response?.body ?? response;
  if (value && !Array.isArray(value) && typeof value === 'object') {
    for (const key of keys) {
      if (Array.isArray(value[key])) return value[key];
    }
    if (value.data && typeof value.data === 'object') {
      for (const key of keys) {
        if (Array.isArray(value.data[key])) return value.data[key];
      }
    }
    return [];
  }
  return Array.isArray(value) ? value : [];
}

const opportunitiesResponse = $('03 - Get Opportunities').first().json;
const risksResponse = $('04 - Get Risks').first().json;
const trendsResponse = $('05 - Get Market Trends').first().json;

// Trích xuất danh sách và chuẩn hóa/cắt gọn nội dung để chống tràn token
const opportunities = extractList(opportunitiesResponse, ['opportunities', 'items', 'results']).slice(0, 20).map(o => ({
  title: o.title ?? '',
  score: o.score ?? o.potential_score ?? 0,
  priority: o.priority ?? '',
  reason: String(o.reason ?? o.description ?? '').slice(0, 200)
}));

const risks = extractList(risksResponse, ['risks', 'items', 'results']).slice(0, 20).map(r => ({
  risk_title: r.risk_title ?? '',
  severity: r.severity ?? '',
  impact_analysis: String(r.impact_analysis ?? '').slice(0, 200),
  mitigation_strategy: String(r.mitigation_strategy ?? '').slice(0, 200)
}));

const trends = extractList(trendsResponse, ['trends', 'market_trends', 'items', 'results']).slice(0, 20).map(t => ({
  topic: t.topic ?? t.name ?? t.title ?? '',
  growth_rate: t.growth_rate ?? t.growthRate ?? 0,
  views: t.views ?? 0,
  likes: t.likes ?? 0,
  category: t.category ?? ''
}));

const hasInputData = opportunities.length > 0 || risks.length > 0 || trends.length > 0;
const analyzedAt = new Date().toISOString();

const prompt = `Bạn là chuyên gia phân tích chiến lược cạnh tranh.
Hãy xây dựng một chiến lược cạnh tranh tổng thể bằng tiếng Việt dựa trên dữ liệu thực tế đã được tổng hợp từ cơ hội, rủi ro và xu hướng bên dưới.

QUY TẮC:
- Chỉ sử dụng bằng chứng có trong dữ liệu đầu vào; không tự bịa số liệu, doanh nghiệp hoặc sự kiện.
- Kết hợp cơ hội, rủi ro và xu hướng (đặc biệt chú ý các chỉ số views, likes, growth_rate và mức độ nghiêm trọng severity) thành một chiến lược thống nhất.
- Nếu dữ liệu của một nhóm bị thiếu, hãy nêu rõ hạn chế đó trong mục tiêu hoặc kết quả kỳ vọng.
- Các bước hành động phải cụ thể, có thứ tự ưu tiên và khả thi.
- Chỉ trả về một JSON hợp lệ, không dùng Markdown hoặc khối code.
- action_steps phải là mảng gồm ít nhất 3 bước.
- expected_outcome phải mô tả kết quả kỳ vọng, không khẳng định kết quả chắc chắn xảy ra.

CẤU TRÚC JSON BẮT BUỘC:
{
  "strategy_title": "Tên chiến lược",
  "objective": "Mục tiêu chiến lược",
  "action_steps": ["Bước 1", "Bước 2", "Bước 3"],
  "expected_outcome": "Kết quả kỳ vọng",
  "supporting_evidence": ["Bằng chứng từ dữ liệu"],
  "limitations": ["Hạn chế của dữ liệu nếu có"]
}

DỮ LIỆU CƠ HỘI (${opportunities.length} bản ghi):
${JSON.stringify(opportunities)}

DỮ LIỆU RỦI RO (${risks.length} bản ghi):
${JSON.stringify(risks)}

DỮ LIỆU XU HƯỚNG (${trends.length} bản ghi):
${JSON.stringify(trends)}

Thời điểm phân tích: ${analyzedAt}`;

return [{
  json: {
    analyzed_at: analyzedAt,
    opportunities,
    risks,
    trends,
    opportunity_count: opportunities.length,
    risk_count: risks.length,
    trend_count: trends.length,
    has_input_data: hasInputData,
    prompt
  }
}];

const result = $input.first().json;
const raw = result.content ?? result.text ?? result.response ?? result.output ?? result.message?.content ?? result.choices?.[0]?.message?.content;

if (typeof raw !== 'string' || !raw.trim()) {
  return [{ json: { parse_ok: false, parse_error: 'Ollama không trả về nội dung văn bản hợp lệ.', raw_response: result } }];
}

let parsed;
try {
  let clean = raw.trim();
  clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('Không tìm thấy đối tượng JSON trong phản hồi AI.');
  parsed = JSON.parse(clean.slice(start, end + 1));
} catch (error) {
  return [{ json: { parse_ok: false, parse_error: error.message, raw_response: raw } }];
}

return [{ json: { ...parsed, parse_ok: true } }];

const d = $input.first().json;
const errors = [];

if (d.parse_ok !== true) {
  errors.push(d.parse_error || 'Không phân tích được JSON từ AI.');
}

const title = String(d.strategy_title ?? d.title ?? d.name ?? '').trim();
const objective = String(d.objective ?? d.description ?? d.reason ?? '').trim();
const outcome = String(d.expected_outcome ?? d.outcome ?? '').trim();

const steps = Array.isArray(d.action_steps)
  ? d.action_steps.map(s => String(s ?? '').trim()).filter(Boolean)
  : [];

const supportingEvidence = Array.isArray(d.supporting_evidence)
  ? d.supporting_evidence.map(e => String(e ?? '').trim()).filter(Boolean)
  : [];

const limitations = Array.isArray(d.limitations)
  ? d.limitations.map(l => String(l ?? '').trim()).filter(Boolean)
  : [];

if (!title) errors.push('Thiếu strategy_title.');
if (!objective) errors.push('Thiếu objective.');
if (steps.length < 3) errors.push('action_steps phải có ít nhất 3 bước.');
if (!outcome) errors.push('Thiếu expected_outcome.');

const ctx = $('06 - Normalize Data and Prepare Prompt').first().json;

const stepsText = steps.join('\n');
const score = Number.isFinite(Number(d.score))
  ? Number(d.score)
  : 0;

const priority = ['low', 'medium', 'high', 'critical'].includes(
  String(d.priority ?? '').trim().toLowerCase()
)
  ? String(d.priority).trim().toLowerCase()
  : 'medium';

// Confidence là điểm tin cậy quy ước dựa trên bằng chứng,
// không phải xác suất thống kê.
const confidence = supportingEvidence.length >= 3
  ? 0.7
  : supportingEvidence.length > 0
    ? 0.5
    : 0.2;

const evidence = {
  objective,
  description: objective,
  action_steps: steps,
  expected_outcome: outcome,
  supporting_evidence: supportingEvidence,
  limitations,
  source_counts: {
    opportunities: ctx.opportunity_count ?? 0,
    risks: ctx.risk_count ?? 0,
    trends: ctx.trend_count ?? 0
  }
};

return [{
  json: {
    is_valid: errors.length === 0,
    validation_errors: errors,

    title,
    name: title,
    strategy_title: title,

    objective,
    reason: objective,
    description: objective,
    summary: objective,

    priority,
    severity: priority,
    level: priority,

    status: 'active',
    category: 'competitive',
    type: 'strategy',

    score,
    strategy_score: score,
    potential_score: score,
    confidence,

    action_steps: steps,
    actions: steps,
    steps,
    recommendations: steps,
    recommended_action: stepsText,
    mitigation_strategy: stepsText,

    expected_outcome: outcome,
    outcome,
    impact: outcome,
    impact_analysis: outcome,

    supporting_evidence: supportingEvidence,
    limitations,
    evidence,

    analyzed_at: ctx.analyzed_at,
    source_counts: evidence.source_counts
  }
}];

